.toolbar {
  display: flex;
  align-items: center;      /* vertical centring in a row */
  gap: 0.5rem;
}
.toolbar .spacer { margin-inline-start: auto; } /* pushes following items to the end */

.stack {
  display: flex;
  flex-direction: column;
  justify-content: center;  /* now vertical */
  align-items: flex-start;  /* now horizontal */
}

.row { display: flex; gap: 1rem; }
.row .avatar { flex: none; width: 40px; }
.row .text {
  flex: 1;
  min-width: 0;            /* allow shrinking below content width */
}
.row .text p {
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

