code.source:
.layout {
  display: grid;
  grid-template-columns: 200px 1fr 2fr;
  grid-auto-rows: minmax(100px, auto);
  gap: 1rem;
}

.page {
  display: grid;
  grid-template-columns: 220px 1fr;
  grid-template-rows: auto 1fr auto;
  grid-template-areas:
    "header header"
    "sidebar main"
    "footer footer";
  min-height: 100dvh;
}
.page > header  { grid-area: header; }
.page > nav     { grid-area: sidebar; }
.page > main    { grid-area: main; }
.page > footer  { grid-area: footer; }

@media (width < 700px) {
  .page {
    grid-template-columns: 1fr;
    grid-template-areas: "header" "main" "sidebar" "footer";
  }
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr));
  gap: 1.5rem;
}

.cards {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 1rem;
}
.card {
  display: grid;
  grid-row: span 3;
  grid-template-rows: subgrid;  /* title, body, footer rows align across cards */
}

.card { position: relative; }
.card .badge {
  position: absolute;
  top: 0.5rem;
  right: 0.5rem;              /* relative to .card's padding box */
}
.site-header {
  position: sticky;
  top: 0;                     /* required threshold */
  z-index: 10;
}
.overlay {
  position: fixed;
  inset: 0;
  background: rgb(0 0 0 / 0.5);
}

/* mobile-first base */
.nav { display: none; }

@media (width >= 48em) {
  .nav { display: flex; }
}

@media (hover: hover) and (pointer: fine) {
  .card:hover { box-shadow: 0 4px 16px rgb(0 0 0 / 0.15); }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}

.card-wrapper {
  container: card / inline-size;
}

.card { display: grid; gap: 1rem; }

@container card (width >= 30rem) {
  .card { grid-template-columns: 10rem 1fr; }
  .card h3 { font-size: clamp(1rem, 4cqi, 1.5rem); }
}

:root {
  --brand: oklch(62% 0.19 255);
  --radius: 0.5rem;
  color-scheme: light dark;
  --bg: light-dark(#ffffff, #0b1020);
  --text: light-dark(#111827, #e5e7eb);
}
body { background: var(--bg); color: var(--text); }
.btn {
  background: var(--btn-bg, var(--brand));
  border-radius: var(--radius);
}
.btn:hover { background: color-mix(in oklch, var(--brand), black 15%); }

@property --angle {
  syntax: "<angle>";
  inherits: false;
  initial-value: 0deg;
}
.spinner {
  background: conic-gradient(from var(--angle), var(--brand), transparent);
  animation: spin 1s linear infinite;
}
@keyframes spin { to { --angle: 360deg; } }

.card {
  padding: 1rem;

  & h2 { margin-block: 0 0.5rem; }
  &:hover { box-shadow: 0 4px 12px rgb(0 0 0 / 0.1); }
  &.is-featured { border: 2px solid var(--brand); }

  @media (width >= 48em) {
    padding: 2rem;
  }
}

.toast {
  transition: opacity 250ms, transform 250ms, display 250ms allow-discrete;
  opacity: 1;
  transform: translateY(0);

  @starting-style {
    opacity: 0;
    transform: translateY(1rem);
  }
}
.toast[hidden] {
  display: none;
  opacity: 0;
  transform: translateY(1rem);
}

